// Positions come from snippets/screenshot-markers.jsx (generated by the capture tool);
// `items` holds the labels in the same order as the manifest's `annotations`.
// Use list="below" for wide (full-page) screenshots.
// Pass the <img> as a child so Mintlify's click-to-zoom applies; the zoom view shows the image without numbers.
export const AnnotatedImage = ({ children, markers = [], items = [], width = 300, markerSize = 24, list = "right" }) => {
  const [active, setActive] = useState(null)
  const [showNumbers, setShowNumbers] = useState(true)
  const position = (n) => markers.find((m) => m.n === n)
  const below = list === "below"

  return (
    <div className="not-prose" style={{ display: "flex", flexDirection: below ? "column" : "row", gap: below ? 16 : 28, alignItems: "flex-start", flexWrap: "wrap", margin: "16px 0" }}>
      <div style={{ width: below ? "100%" : width, maxWidth: "100%", flexShrink: 0 }}>
      <div style={{ position: "relative", lineHeight: 0 }}>
        {children}
        {showNumbers &&
          items.map((item, i) => {
            const m = position(i + 1)
            if (!m) return null
            const isActive = active === m.n
            return (
              <span
                key={m.n}
                aria-hidden="true"
                onMouseEnter={() => setActive(m.n)}
                onMouseLeave={() => setActive(null)}
                style={{
                  position: "absolute",
                  left: `${m.x}%`,
                  top: `${m.y}%`,
                  transform: `translate(-50%, -50%) scale(${isActive ? 1.3 : 1})`,
                  display: "inline-flex",
                  alignItems: "center",
                  justifyContent: "center",
                  width: markerSize,
                  height: markerSize,
                  boxSizing: "border-box",
                  borderRadius: "50%",
                  background: isActive ? "#15803D" : "#16A34A",
                  color: "#fff",
                  font: `700 ${markerSize < 24 ? 11 : 12}px/1 system-ui, sans-serif`,
                  border: "2px solid #fff",
                  boxShadow: isActive ? "0 0 0 4px rgba(22,163,74,.4), 0 1px 3px rgba(0,0,0,.35)" : "0 1px 3px rgba(0,0,0,.35)",
                  transition: "transform 120ms, background 120ms",
                  zIndex: isActive ? 2 : 1,
                }}
              >
                {m.n}
              </span>
            )
          })}
      </div>
        <label style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 10, font: "500 14px/1.4 system-ui, sans-serif", cursor: "pointer" }}>
          <span>Show numbers on the screen</span>
          <button
            type="button"
            role="switch"
            aria-checked={showNumbers}
            onClick={() => setShowNumbers(!showNumbers)}
            style={{
              position: "relative",
              width: 36,
              height: 20,
              padding: 0,
              borderRadius: 999,
              border: "none",
              background: showNumbers ? "#16A34A" : "rgba(127,127,127,.45)",
              cursor: "pointer",
              transition: "background 150ms",
              flexShrink: 0,
            }}
          >
            <span
              style={{
                position: "absolute",
                top: 2,
                left: showNumbers ? 18 : 2,
                width: 16,
                height: 16,
                borderRadius: "50%",
                background: "#fff",
                boxShadow: "0 1px 2px rgba(0,0,0,.3)",
                transition: "left 150ms",
              }}
            />
          </button>
        </label>
      </div>
      <div style={{ flex: below ? "1 1 auto" : "1 1 200px", minWidth: 0 }}>
        <ol style={{ listStyle: "none", padding: 0, margin: 0, display: "grid", gap: 2 }}>
          {items.map((item, i) => {
            const isActive = active === i + 1
            return (
              <li
                key={i}
                onMouseEnter={() => setActive(i + 1)}
                onMouseLeave={() => setActive(null)}
                style={{
                  display: "flex",
                  gap: 8,
                  padding: "5px 10px",
                  borderRadius: 6,
                  borderLeft: `3px solid ${isActive ? "#16A34A" : "transparent"}`,
                  background: isActive ? "rgba(22,163,74,.16)" : "transparent",
                  font: "400 14px/1.5 system-ui, sans-serif",
                  transition: "background 120ms",
                }}
              >
                <span style={{ minWidth: 24, fontWeight: 600, fontVariantNumeric: "tabular-nums" }}>{i + 1}.</span>
                <span>
                  <strong>{item.title}</strong>
                  {item.text ? `: ${item.text}` : ""}
                </span>
              </li>
            )
          })}
        </ol>
      </div>
    </div>
  )
}
